"""Explicit financial columns from the existing transcriptions; no PDF access."""
import json, subprocess, hashlib
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parent.parent
exams=json.loads(subprocess.check_output(['node',str(ROOT/'scripts/exam-practice-source.mjs'),'--json']))
sources={e['id']+'/'+q['id']:q for e in exams for q in e['questions']}
out={}
def table(headers,rows,caption):
    assert all(len(row)==len(headers) for row in rows),caption
    return '<div class="table-wrap"><table class="practice-answer-table"><caption>'+escape(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(text):return '<p>'+escape(text)+'</p>'
def entry(key,html):
    key='cafa2-'+key
    out[key]={'sourceSha256':hashlib.sha256(sources[key]['solutionHtml'].encode()).hexdigest(),'display':[html]}
def share(rows,part,caption):return table(['Omschrijving','100% (€)',part+' (€)'],rows,caption)
def calc(rows,caption):return table(['Omschrijving / berekening','Bedrag (€)'],rows,caption)
def fx(rows,currency,caption):return table(['Omschrijving / datum','Bedrag ('+currency+')','Koers (€ per '+currency+')','Bedrag (€)'],rows,caption)
def stock(rows,currency,caption):return table(['Datum / voorraadlaag','Aantal','Prijs ('+currency+')','Bedrag ('+currency+')','Koers (€ per '+currency+')','Bedrag (€)'],rows,caption)

